		$edit        = false;
		$params_only = true;
		$homeurl     = "https://transposh.org";
		$permalinks  = true;
		$this->assertEquals( "?lang=he", Utilities::rewrite_url_lang_param( "", $homeurl, $permalinks, "he", $edit, $params_only ) );
